"use client";

import { useState, useEffect } from "react";
import Header from "@/components/common/Header";
import Navbar from "@/components/common/Navbar";
import UserSidebar from "@/components/common/UserSidebar";
import Footer from "@/components/common/Footer";

const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL;

const UserProfilePage = () => {
  const [user, setUser] = useState({
    id: null,
    fullname: "",
    email: "",
    photoProfileUrl: null,
    birthDate: "",
    gender: "",
    isVerified: false,
  });

  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    fetchUserProfile();
  }, []);

  const fetchUserProfile = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("accessToken"); 
      if (!token) {
        console.error("User not authenticated");
        setLoading(false);
        return;
      }
      
      const response = await fetch(`${BACKEND_URL}/api/v1/user/profile`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      
      const userData = data.data;
      
      const formattedUser = {
        id: userData.id,
        fullname: userData.fullname,
        email: userData.email,
        photoProfileUrl: userData.photoProfileUrl || "/default-avatar.png",
        birthDate: userData.birthDate ? userData.birthDate.split("T")[0] : "",
        gender: userData.gender,
        isVerified: userData.isVerified,
      };
  
      setUser(formattedUser);
    } catch (error) {
      console.error("Error fetching user profile:", error);
    } finally {
      setLoading(false);
    }
  };
  
  const handleResetPassword = async () => {
    setLoading(true);
    setError(null);
    setSuccess(false);
    
    try {
      const response = await fetch(`${BACKEND_URL}/api/v1/user/reset-password`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: user.email }),
      });
      
      if (!response.ok) {
        throw new Error("Failed to send reset link. Please try again.");
      }
      
      setSuccess(true);
    } catch (error: any) {
      setError(error.message || "An error occurred while sending the reset link.");
    } finally {
      setLoading(false);
    }
  };
  
  return (
    <>
      <Header />
      <Navbar />
      <div className="flex text-black min-h-screen bg-gray-100">
        <UserSidebar />
        <div className="container mx-auto p-6">
          <h1 className="text-2xl font-bold mb-6">👤 User Profile</h1>
  
          {loading ? (
            <p className="text-center text-gray-500 animate-pulse">Loading...</p>
          ) : (
            <>
              {/* User Information */}
              <div className="mb-6 p-6 border border-gray-200 rounded-xl shadow-md bg-white">
                <h2 className="text-xl font-semibold mb-2">User Information</h2>
                <p><strong>Name:</strong> {user.fullname}</p>
                <p><strong>Email:</strong> {user.email}</p>
                <p><strong>Birth Date:</strong> {user.birthDate || "N/A"}</p>
                <p><strong>Gender:</strong> {user.gender || "N/A"}</p>
                <p><strong>Status:</strong> {user.isVerified ? "✅ Verified" : "❌ Unverified"}</p>
              </div>
  
              {/* Reset Password */}
              {user.id && !user.email.includes("google.com") && (
                <section className="mb-6 p-6 border border-gray-200 rounded-xl shadow-md bg-white">
                  <h2 className="text-xl font-semibold mb-2">Reset Password</h2>
                  {success ? (
                    <p className="text-green-600 font-semibold">Password reset link sent! Check your email.</p>
                  ) : (
                    <button 
                      className="px-5 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-transform duration-200 ease-in-out hover:scale-105 active:scale-95"
                      onClick={handleResetPassword}
                      disabled={loading}
                    >
                      {loading ? "Sending..." : "Reset Password"}
                    </button>
                  )}
                  {error && <p className="text-red-500 font-semibold mt-2">{error}</p>}
                </section>
              )}
            </>
          )}
        </div>
      </div>
      <Footer />
    </>
  );
};

export default UserProfilePage;
